import math
refl_anti = lambda p: (8 - p[1], 8 - p[0])   # undo fold 2: mirror in x + y = 8
refl_diag = lambda p: (p[1], p[0])           # undo fold 1: mirror in y = x
h = {(7, 3)}
h |= {refl_anti(p) for p in h}
h |= {refl_diag(p) for p in h}
v = sorted(h, key=lambda p: math.atan2(p[1] - 4, p[0] - 4))
area = abs(sum(v[i][0] * v[(i + 1) % 4][1] - v[(i + 1) % 4][0] * v[i][1] for i in range(4))) / 2
print(sorted(h), area)
