from collections import Counter
def gen(k, lo, rem):
    if k == 1:
        if rem >= lo:
            yield (rem,)
        return
    v = lo
    while v * k <= rem:
        for r in gen(k - 1, v, rem - v):
            yield (v,) + r
        v += 1
largest = []
for t in gen(7, 1, 70):
    c = Counter(t)
    top = max(c.values())
    if t[3] == 9 and [v for v in c if c[v] == top] == [7]:
        largest.append(t[-1])
print(min(largest), len(largest))
